class Solution {
  public long minimumPerimeter(long neededApples) {
    long lo = 0, hi = 1;
    while (apples(hi) < neededApples) hi <<= 1;
    while (lo < hi) {
      long mid = lo + (hi - lo) / 2;
      if (apples(mid) >= neededApples) hi = mid;
      else lo = mid + 1;
    }
    return 8 * lo;
  }

  private long apples(long side) {
    return 2 * side * (side + 1) * (2 * side + 1);
  }
}
